inline LocalizedMessage electricityFieldMessage(std::string_view language,ElectricityFieldMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=electricityFieldMessageKeyCount)return {};
    const auto &source=electricityFieldLocalePacks()[0];const auto *selected=&source;for(const auto &pack:electricityFieldLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string electricityFieldEnglish(ElectricityFieldMessageKey key){return std::string(electricityFieldMessage("en",key).text);}
